Here is a demonstration of a common vulnerability in Java web applications: **SQL Injection** caused by improper use of the JDBC API (specifically, concatenating user input directly into SQL strings).

```java
import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;

public class VulnerableExample {
    public void searchUser(Connection conn, String username) throws Exception {
        // This code is vulnerable to SQL injection because user input is directly concatenated into the SQL query.
        String query = "SELECT * FROM users WHERE username = '" + username + "'";

        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(query);

        while (rs.next()) {
            System.out.println("User found: " + rs.getString("username"));
        }

        rs.close();
        stmt.close();
    }
}
```
***
```java
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureExample {
    public void searchUser(Connection conn, String username) throws Exception {
        // Use a PreparedStatement with parameterized queries to prevent SQL injection.
        // The database driver handles escaping and type safety automatically.
        String query = "SELECT * FROM users WHERE username = ?";

        PreparedStatement pstmt = conn.prepareStatement(query);
        pstmt.setString(1, username); // Safely bind the user input to the placeholder

        ResultSet rs = pstmt.executeQuery();

        while (rs.next()) {
            System.out.println("User found: " + rs.getString("username"));
        }

        rs.close();
        pstmt.close();
    }
}
